function runtime_fixed_versions()
{
    return array('8.2'=>'8.2.35', '8.3'=>'8.3.36', '8.4'=>'8.4.27', '8.5'=>'8.5.12');
}
function runtime_patch_assessment($version)
{
    $fixed=runtime_fixed_versions();$parts=explode('.',$version);$branch=implode('.',array_slice($parts,0,2));
    if(preg_match('/(?:alpha|beta|RC|dev)/i',$version))return array('review','Development build: provider review required','Use a patched production release. Prerelease builds are not assessed by this tool.','Not assessed');
    if(!isset($fixed[$branch])){
        if(version_compare($version,'8.2.0','<'))return array('warning','Update PHP: this branch is no longer supported upstream','Move to a supported, patched PHP release. If your provider maintains this older branch, require confirmation of both security backports.','Supported patched branch');
        return array('review','This PHP branch is not in the advisory table','Check the current official PHP advisory and ask your provider to confirm the fixes. An unknown branch is not automatically safe or vulnerable.','Not assessed');
    }
    if(version_compare($version,$fixed[$branch],'>='))return array('match','Published version fix level met','This version meets the upstream fixes for the two October 21 critical issues. This is a version comparison, not binary patch verification or a security certificate.',$fixed[$branch]);
    return array('warning','Update PHP: below the published security-fix version','Ask your hosting provider to update to '.$fixed[$branch].' or a later patched release in this branch, or confirm that both fixes are backported into this exact build. Until confirmed, treat the patch status as unresolved.',$fixed[$branch]);
}
function runtime_upload_state($value)
{
    if($value===false)return 'unknown';
    return in_array(strtolower(trim((string)$value)),array('','0','off','false','no'),true)?'off':'on';
}
function runtime_escape($value){return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
